def _root():
    raw=os.environ.get("MARK56_WORKSPACE","").strip()
    root=Path(raw).expanduser() if raw else Path.cwd()
    root=root.resolve()
    if not root.is_dir(): raise ValueError("Configured workspace directory does not exist.")
    return root

def _name(value):
    name=str(value or "").strip()
    if not name or len(name)>48 or name in {".",".."}: raise ValueError("Project name must contain 1–48 characters.")
    if any(ch not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_" for ch in name):
        raise ValueError("Project name may contain only letters, numbers, hyphens, and underscores.")
    return name

def run(parameters: dict, **_context) -> str:
    p=parameters or {}; operation=str(p.get("operation") or "list").strip().lower()
    if operation=="list":
        return json.dumps({"ok":True,"templates":sorted(_TEMPLATES),"note":"Built-in templates work without an AI provider; they are starters, not general-purpose reasoning."})
    if operation not in {"preview","create"}: return json.dumps({"ok":False,"message":"Use list, preview, or create."})
    try:
        template=str(p.get("template") or "").strip().lower(); name=_name(p.get("name") or "")
        if template not in _TEMPLATES: raise ValueError("Template must be portfolio, webapp, or game.")
        root=_root(); destination=(root/name).resolve()
        if not destination.is_relative_to(root): raise ValueError("Project destination escapes the configured workspace.")
        files=_TEMPLATES[template]
        plan={"ok":True,"operation":operation,"template":template,"destination":str(destination),"files":list(files),"requires_provider":False,"limitations":["Built-in starter only; not a custom solution to arbitrary requirements.","No backend, database, deployment, or production security is implied."]}
        if operation=="preview": return json.dumps(plan,ensure_ascii=False)
        if p.get("confirmed") is not True:
            plan.update(ok=False,message="Preview first, then pass confirmed=true to create the files.")
            return json.dumps(plan,ensure_ascii=False)
        if destination.exists(): raise FileExistsError("Destination already exists; existing files are never overwritten.")
        destination.mkdir(parents=False,exist_ok=False)
        try:
            for relative,content in files.items(): (destination/relative).write_text(content,encoding="utf-8")
            plan.update(operation="created",message="Starter project created; no external AI provider was used.")
            return json.dumps(plan,ensure_ascii=False)
        except Exception:
            import shutil
            shutil.rmtree(destination,ignore_errors=True)
            raise
    except (ValueError,OSError) as exc: return json.dumps({"ok":False,"message":str(exc)},ensure_ascii=False)

